ManifestManagerAsyncWaiter::ManifestManagerAsyncWaiter(
    ManifestManager* proxy) : proxy_(proxy) {}

ManifestManagerAsyncWaiter::~ManifestManagerAsyncWaiter() = default;


void ManifestManagerAsyncWaiter::RequestManifest(
    ::blink::mojom::ManifestRequestResult* out_result, ::GURL* out_url, ::blink::mojom::ManifestPtr* out_manifest) {
  base::RunLoop loop;
  proxy_->RequestManifest(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::blink::mojom::ManifestRequestResult* out_result
,
             ::GURL* out_url
,
             ::blink::mojom::ManifestPtr* out_manifest
,
             ::blink::mojom::ManifestRequestResult result,
             const ::GURL& url,
             ::blink::mojom::ManifestPtr manifest) {*out_result = std::move(result);*out_url = std::move(url);*out_manifest = std::move(manifest);
            loop->Quit();
          },
          &loop,
          out_result,
          out_url,
          out_manifest));
  loop.Run();
}



void ManifestManagerAsyncWaiter::RequestManifestDebugInfo(
    ::GURL* out_url, ::blink::mojom::ManifestPtr* out_parsed_manifest, ::blink::mojom::ManifestDebugInfoPtr* out_debug_info) {
  base::RunLoop loop;
  proxy_->RequestManifestDebugInfo(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::GURL* out_url
,
             ::blink::mojom::ManifestPtr* out_parsed_manifest
,
             ::blink::mojom::ManifestDebugInfoPtr* out_debug_info
,
             const ::GURL& url,
             ::blink::mojom::ManifestPtr parsed_manifest,
             ::blink::mojom::ManifestDebugInfoPtr debug_info) {*out_url = std::move(url);*out_parsed_manifest = std::move(parsed_manifest);*out_debug_info = std::move(debug_info);
            loop->Quit();
          },
          &loop,
          out_url,
          out_parsed_manifest,
          out_debug_info));
  loop.Run();
}



void ManifestManagerAsyncWaiter::ParseManifestFromString(
    const ::GURL& document_url, const ::GURL& manifest_url, const std::string& manifest_content, ::blink::mojom::ManifestPtr* out_parsed_manifest) {
  base::RunLoop loop;
  proxy_->ParseManifestFromString(
      std::move(document_url),
      std::move(manifest_url),
      std::move(manifest_content),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::blink::mojom::ManifestPtr* out_parsed_manifest
,
             ::blink::mojom::ManifestPtr parsed_manifest) {*out_parsed_manifest = std::move(parsed_manifest);
            loop->Quit();
          },
          &loop,
          out_parsed_manifest));
  loop.Run();
}

::blink::mojom::ManifestPtr ManifestManagerAsyncWaiter::ParseManifestFromString(
    const ::GURL& document_url, const ::GURL& manifest_url, const std::string& manifest_content) {
  ::blink::mojom::ManifestPtr async_wait_result;
  ParseManifestFromString(std::move(document_url),std::move(manifest_url),std::move(manifest_content),&async_wait_result);
  return async_wait_result;
}






